/**
 * Default synthetic PDFs for the demo intake form.
 *
 * The files live in apps/web/public/demo-documents and are generated by
 * data/demo_documents/generate_demo_documents.py. They are clearly watermarked
 * and contain fictional data only.
 */

export const DEMO_DOCUMENT_FILES: Record<string, string> = {
  doc_eoa_app: "doc_eoa_app.pdf",
  doc_prev_eoa: "doc_prev_eoa.pdf",
  doc_univ_affil: "doc_univ_affil.pdf",
  doc_fire_safety: "doc_fire_safety.pdf",
  doc_building_stability: "doc_building_stability.pdf",
  doc_infra_photos: "doc_infra_photos.pdf",
  doc_land_documents: "doc_land_documents.pdf",
  doc_faculty_cadre: "doc_faculty_cadre.pdf",
  doc_anti_ragging: "doc_anti_ragging.pdf",
  doc_barrier_free: "doc_barrier_free.pdf",
};

export function hasDemoDocument(documentType: string): boolean {
  return Boolean(DEMO_DOCUMENT_FILES[documentType]);
}

export async function loadDemoDocumentFile(documentType: string): Promise<File> {
  const filename = DEMO_DOCUMENT_FILES[documentType];
  if (!filename) {
    throw new Error(`No demo sample PDF is configured for '${documentType}'.`);
  }

  const response = await fetch(`/demo-documents/${filename}`, { cache: "no-store" });
  if (!response.ok) {
    throw new Error(`Could not load demo PDF '${filename}'.`);
  }

  const blob = await response.blob();
  return new File([blob], filename, { type: "application/pdf" });
}

export async function loadDemoDocumentFiles(
  documentTypes: string[]
): Promise<Array<[string, File]>> {
  const supported = documentTypes.filter(hasDemoDocument);
  const results = await Promise.allSettled(
    supported.map(async (documentType) => {
      const file = await loadDemoDocumentFile(documentType);
      return [documentType, file] as [string, File];
    })
  );

  const loaded: Array<[string, File]> = [];
  const failures: string[] = [];
  results.forEach((result, index) => {
    if (result.status === "fulfilled") {
      loaded.push(result.value);
    } else {
      failures.push(supported[index]);
    }
  });

  if (loaded.length === 0) {
    throw new Error(
      failures.length > 0
        ? "The demo PDFs could not be loaded. Attach files manually or retry."
        : "No demo PDFs are available for this checklist."
    );
  }

  return loaded;
}
